package com.bank.spark.model;

// A row with its bucketing key and the computed bucket number.
public class BucketedRow {
    private final String table;
    private final String accountId;
    private final int bucket;

    public BucketedRow(String table, String accountId, int bucket) {
        this.table = table;
        this.accountId = accountId;
        this.bucket = bucket;
    }

    public String getTable() { return table; }
    public String getAccountId() { return accountId; }
    public int getBucket() { return bucket; }
}
