package com.bank.spark.service;

// Mimics bucketBy(n, "accountId"): hash-modulo into a fixed bucket count.
public class BucketAssigner {
    private final int numBuckets;

    public BucketAssigner(int numBuckets) {
        this.numBuckets = numBuckets;
    }

    // Same key → same bucket, deterministically, regardless of table.
    public int bucketFor(String accountId) {
        return Math.floorMod(accountId.hashCode(), numBuckets);
    }

    public int getNumBuckets() { return numBuckets; }
}
