package com.bank.spark;

import com.bank.spark.model.BucketedRow;
import com.bank.spark.service.BucketAssigner;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class BucketingDemo {

    private static final Logger log = Logger.getLogger(BucketingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        handler.setLevel(Level.ALL);
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Both tables bucketed by accountId into the SAME 8 buckets.
        BucketAssigner assigner = new BucketAssigner(8);
        String[] accounts = {"SAV2001", "CUR3001", "SAV2002", "CUR3002"};

        List<BucketedRow> transactions = new ArrayList<>();
        List<BucketedRow> accountsTbl = new ArrayList<>();
        for (String acct : accounts) {
            int b = assigner.bucketFor(acct);
            transactions.add(new BucketedRow("transactions", acct, b));
            accountsTbl.add(new BucketedRow("accounts", acct, b));
        }

        log.info(() -> "bucketBy(8, \"accountId\") on BOTH tables:");
        for (int i = 0; i < accounts.length; i++) {
            BucketedRow t = transactions.get(i);
            BucketedRow a = accountsTbl.get(i);
            log.info(t.getAccountId() + " -> transactions bucket " + t.getBucket()
                    + ", accounts bucket " + a.getBucket()
                    + (t.getBucket() == a.getBucket() ? "  (SAME → shuffle-free join)" : "  (MISMATCH)"));
        }

        boolean allMatch = true;
        for (int i = 0; i < accounts.length; i++) {
            if (transactions.get(i).getBucket() != accountsTbl.get(i).getBucket()) allMatch = false;
        }
        if (allMatch) {
            log.info("Every account lands in the same bucket on both tables — join bucket-to-bucket, NO shuffle.");
        } else {
            log.severe("Bucket mismatch — cannot do a shuffle-free join.");
        }

        log.info(() -> "Fixed " + assigner.getNumBuckets() + " buckets regardless of millions of accounts — no directory explosion.");
    }
}

